tools.example:
model.study("std2").feature("uq").set("uqtype", "screening");
model.study("std2").feature("uq").set("partitionlevel", "lvl6");
// results: Quantities of Interest table + MOAT table (mean, std of elementary effects) with 1D annotation plots

model.study("std2").feature("uq").set("uqtype", "sensitivityanalysis");
// outputs: QoI table, Sobol table, Sobol training error table, Sobol Index plots (one per QoI)
// Application Library: ishigami_function_uncertainty_quantification, solidly_mounted_resonator_2d_uncertainty_quantification

model.study("std2").feature("uq").set("uqtype", "uncertaintypropagation");
// results: QoI Confidence interval table, UP predicted QoI table (feeds KDE datasets), Uncertainty Quantification plot group with KDE plots
// Application Library: microstrip_patch_antenna_uq, bracket_uncertainty_quantification

model.study("std2").feature("uq").set("uqtype", "reliabilityanalysis");
model.study("std2").feature("uq").set("rafailure", "parallel");
// results: Probability for conditions table, maximum expected feasibility function tables, RA predicted QoI
// Application Library: bowtie_antenna_optimization, bracket_uncertainty_quantification

model.func().create("pce1", "PolynomialChaosExpansion");
model.func("pce1").set("source", "resultTable");
model.func("pce1").set("resultTable", "tbl1");
model.func("pce1").set("qnorm", "0.5");
model.func("pce1").run();  // train

model.result().dataset().create("kde1", "KernelDensityEstimation");
model.result().dataset("kde1").set("table", "tbl3");
model.result().create("pg5", "PlotGroup1D");
model.result("pg5").set("data", "kde1");
// Application Library: ishigami_function_direct_monte_carlo

model.study().create("std3");
model.study("std3").create("sm", "SurrogateModelTraining");
model.study("std3").feature("sm").set("surrogatemodel", "dnn");
model.study("std3").feature("sm").set("automatictraining", "on");
// the trained function (dnn1) can then drive a fast app or an optimization

model.component("comp1").geom("geom1").geomRep("comsol");
model.component("comp1").geom("geom1").run();
// then Study toolbar > Update Solution to map the existing solution onto the rebuilt COMSOL-kernel geometry
